// 言語と国の組み合わせ（言語タブ）
window.LANGS = [
  { lang: 'ja', country: 'jp', label: '日本語' },
  { lang: 'en', country: 'us', label: 'English' },
]

// 英語の冠詞（a / an）
// 文の途中では先頭を小文字に（"AI ..." や "HR ..." のような略語は残す）
const lower1 = s => (s.length > 1 && s[1] === s[1].toLowerCase() ? s[0].toLowerCase() + s.slice(1) : s)
const article = s => (/^[aeiou]/i.test(s) && !/^(uni|use|usu|eu|one)/i.test(s) ? 'an ' : 'a ') + lower1(s)

window.t = function (key, vars = {}) {
  const C = window.COUNTRY || {}
  const lang = (C.lang) || document.documentElement.lang || 'ja'
  const dict = window.I18N[lang] || {}
  const get = k => (C.text && C.text[k]) ?? dict[k] ?? (lang === 'ja' ? undefined : undefined) ?? window.I18N.ja[k]
  // n が 1 のときは単数形の文（key.one）があればそちらを使う
  if (vars.n === 1 && ((C.text && C.text[key + '.one']) || dict[key + '.one'])) key = key + '.one'
  // 英語では {title} / {job} に冠詞をつけた {aTitle} / {aJob} も使えるようにする
  if (lang === 'en') {
    vars = { ...vars }
    if (typeof vars.title === 'string') vars.aTitle = article(vars.title)
    if (typeof vars.job === 'string') vars.aJob = article(vars.job)
    if (typeof vars.emp === 'string') vars.emp = lower1(vars.emp)
  }
  const s = get(key) ?? key
  return s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '').replace(/ {2,}/g, ' ')
}
